// recovered via the fetcher and the cat-file fallback.
func (s *V2GitStore) wrapWithFetcher(ctx context.Context, tree *object.Tree) *FetchingTree {
	return NewFetchingTree(ctx, tree, s.repo.Storer, s.blobFetcher)
}

